{"command": "python3 - <<'PY'
import json
p='/workspace/contracts/openapi.contract.json'
d=json.load(open(p))
print('paths',len(d['paths']))
for path,item in d['paths'].items():
    for method,op in item.items():
        if method.lower() in {'get','post','put','patch','delete'}:
            print(method.upper(),path,op.get('operationId'), 'body=', bool(op.get('requestBody')), 'params=', [(x['name'],x['in'],x.get('required')) for x in op.get('parameters',[])])
print('\nschemas',len(d.get('components',{}).get('schemas',{})))
print('\n'.join(d.get('components',{}).get('schemas',{}).keys()))
PY", "security_risk": "LOW", "summary": "Summarize API operations and schemas"}

{"command": "python3 - <<'PY'
import json
D=json.load(open('/workspace/contracts/openapi.contract.json'))
for path,item in D['paths'].items():
 for m,op in item.items():
  if m not in ('get','post'): continue
  print('\n###',m.upper(),path,op['operationId'])
  rb=op.get('requestBody',{}).get('content',{}).get('application/json',{}).get('schema')
  print('REQ',json.dumps(rb,separators=(',',':')) if rb else '-')
  for code,r in op['responses'].items():
   s=r.get('content',{}).get('application/json',{}).get('schema')
   print('RESP',code,json.dumps(s,separators=(',',':')) if s else '-')
PY", "security_risk": "LOW", "summary": "Extract complete operation request and response schemas"}

{"command": "python3 - <<'PY'
import json
D=json.load(open('/workspace/contracts/openapi.contract.json'))
for n,s in D['components']['schemas'].items(): print('\n###',n, json.dumps(s,indent=2))
PY", "timeout": 10, "security_risk": "LOW", "summary": "Inspect reusable contract schema definitions"}

