func coord(m map[string]any) map[string]any { if v,ok:=m["coordinate"].(map[string]any);ok{return v};return nil }
func validCoord(c map[string]any) bool { return c!=nil && num(c,"latitude")>=-90 && num(c,"latitude")<=90 && num(c,"longitude")>=-180 && num(c,"longitude")<=180 }
func distance(a,b map[string]any) float64 { if !validCoord(a)||!validCoord(b){return 1e9}; p:=math.Pi/180; dlat:=(num(b,"latitude")-num(a,"latitude"))*p;dlon:=(num(b,"longitude")-num(a,"longitude"))*p; x:=math.Sin(dlat/2)*math.Sin(dlat/2)+math.Cos(num(a,"latitude")*p)*math.Cos(num(b,"latitude")*p)*math.Sin(dlon/2)*math.Sin(dlon/2);return 6371*2*math.Atan2(math.Sqrt(x),math.Sqrt(1-x)) }
