type Sample struct { ID, RequestID, RequesterID, JourneyID, TypeID, Status, OriginType, CurrentHolderID, TargetLabID string; Origin map[string]any; RequestedAt, Deadline, Earliest, Latest, SealedAt, LocationAt string; Container string; Tmin, Tmax float64; Incompatible []string; Sealed bool; Exception map[string]any; Timeline []map[string]any; ActiveAssignments []string; Location map[string]any }
type Journey struct { ID string; PlanVersion int; RouteMode, Status string; EstimatedDelivery string; Cost float64; CapacityUsed, CapacityAvailable int; SampleIDs []string; Stops []map[string]any; Legs []map[string]any; AssignmentIDs []string; ParentID string; ReplanStatus string }
