adySealed":pre};if reason!="serviceable"{out["serviceabilityReason"]=reason};if lab!=nil{out["targetLaboratoryId"]=lab.ID};if s.JourneyID!=""{out["journeyId"]=s.JourneyID};dataJSON(w,201,out)}

