package main

import (
    "crypto/rand"
    "crypto/sha256"
    "encoding/hex"
    "encoding/json"
    "fmt"
    "io"
    "log"
    "math"
    "net/http"
    "os"
    "path/filepath"
    "sort"
    "strconv"
    "strings"
    "sync"
    "time"
)

type User struct { ID, Username, PasswordHash, Email, FullName, Phone string; Roles, Qualifications []string; Certifications []map[string]any; Active bool; AssignedLocationID, ActiveRole string; Available bool; CapacityUnits int; Location map[string]any; AssignmentCount int }
type Location struct { ID, Name string; Coordinate map[string]any; CoverageKm float64; HandlingMinutes int; Active bool; Functions map[string]bool; Capacity, CooledCapacity, Reserved, CooledReserved int; Accepted map[string]bool }
type Connection struct { ID, From, To string; Travel int; Cost float64; Cooled, Active bool; Capacity, CooledCapacity, Reserved, CooledReserved int }
type SampleType struct { ID, Name, RequiredQualification, ContainerType string; Qualified, Cooled, Batching bool; Tmin, Tmax float64; Incompatible []string }
type Sample struct { ID, RequestID, RequesterID, JourneyID, TypeID, Status, OriginType, CurrentHolderID, TargetLabID string; Origin map[string]any; RequestedAt, Deadline, Earliest, Latest, SealedAt, LocationAt string; Container string; Tmin, Tmax float64; Incompatible []string; Sealed bool; Exception map[string]any; Timeline []map[string]any; ActiveAssignments []string; Location map[string]any }
type Journey struct { ID string; PlanVersion int; RouteMode, Status string; EstimatedDelivery string; Cost float64; CapacityUsed, CapacityAvailable int; SampleIDs []string; Stops []map[string]any; Legs []map[string]any; AssignmentIDs []string; ParentID string; ReplanStatus string }
type Assignment struct { ID, Kind, SampleID, JourneyID, From, To, WorkerID, Status string; Sequence int; OfferExpires string; NodeID, LabID string; History []map[string]any }
type Handoff struct { ID, SampleID, SenderID, ReceiverID, Status string; SenderConfirmed, ReceiverConfirmed bool; CreatedAt string }
type Audit struct { ID, ActorID, Role, Action, EntityType, EntityID string; Success bool; At string; Details map[string]any }
type State struct { Users map[string]*User; Locations map[string]*Location; Connections map[string]*Connection; SampleTypes map[string]*SampleType; Samples map[string]*Sample; Requests map[string]map[string]any; Journeys map[string]*Journey; Assignments map[string]*Assignment; Handoffs map[string]*Handoff; Audits []Audit; Events []map[string]any; Sessions map[string]string; Idempotency map[string]json.RawMessage; ServiceVersion int; NetworkRevision int; EventSeq int }

type App struct { mu sync.RWMutex; state State; file string }

func uuid() string { b:=make([]byte,16); if _,e:=rand.Read(b);e!=nil { return fmt.Sprintf("%d",time.Now().UnixNano()) }; b[6]=(b[6]&15)|64; b[8]=(b[8]&63)|128; return fmt.Sprintf("%08x-%04x-%04x-%04x-%012x",b[0:4],b[4:6],b[6:8],b[8:10],b[10:]) }
func now() string { return time.Now().UTC().Format(time.RFC3339Nano) }
func hash(s string) string { x:=sha256.Sum256([]byte(s)); return hex.EncodeToString(x[:]) }
func str(m map[string]any,k string) string { if v,ok:=m[k].(string);ok{return v};return "" }
func boolv(m map[string]any,k string, d bool) bool { if v,ok:=m[k].(bool);ok{return v};return d }
func num(m map[string]any,k string) float64 { if v,ok:=m[k].(float64);ok{return v};if v,ok:=m[k].(int);ok{return float64(v)};return 0 }
func intval(m map[string]any,k string) int { return int(num(m,k)) }
func arr(m map[string]any,k string) []any { if v,ok:=m[k].([]any);ok{return v};return nil }
func idarr(m map[string]any,k string) []string { out:=[]string{};for _,x:=range arr(m,k){if s,ok:=x.(string);ok{out=append(out,s)}};return out }
func iso(v string) time.Time { t,_:=time.Parse(time.RFC3339Nano,v);return t }
func coord(m map[string]any) map[string]any { if v,ok:=m["coordinate"].(map[string]any);ok{return v};return nil }
func validCoord(c map[string]any) bool { return c!=nil && num(c,"latitude")>=-90 && num(c,"latitude")<=90 && num(c,"longitude")>=-180 && num(c,"longitude")<=180 }
func distance(a,b map[string]any) float64 { if !validCoord(a)||!validCoord(b){return 1e9}; p:=math.Pi/180; dlat:=(num(b,"latitude")-num(a,"latitude"))*p;dlon:=(num(b,"longitude")-num(a,"longitude"))*p; x:=math.Sin(dlat/2)*math.Sin(dlat/2)+math.Cos(num(a,"latitude")*p)*math.Cos(num(b,"latitude")*p)*math.Sin(dlon/2)*math.Sin(dlon/2);return 6371*2*math.Atan2(math.Sqrt(x),math.Sqrt(1-x)) }
func copyMap(m map[string]any) map[string]any { b,_:=json.Marshal(m);var o map[string]any;json.Unmarshal(b,&o);return o }

func newState() State { return State{Users:map[string]*User{},Locations:map[string]*Location{},Connections:map[string]*Connection{},SampleTypes:map[string]*SampleType{},Samples:map[string]*Sample{},Requests:map[string]map[string]any{},Journeys:map[string]*Journey{},Assignments:map[string]*Assignment{},Handoffs:map[string]*Handoff{},Sessions:map[string]string{},Idempotency:map[string]json.RawMessage{},ServiceVersion:1} }
