func requireAuth(a *App,w http.ResponseWriter,r *http.Request)(*User,string,bool){u,role,ok:=a.auth(r);if !ok{errJSON(w,401,"unauthorized","authentication required")};return u,role,ok}
func requireRole(w http.ResponseWriter,u *User,role string)bool{if u==nil{return false};if u.ActiveRole==""{errJSON(w,409,"role_not_selected","select an active role first");return false};if u.ActiveRole!=role&&u.ActiveRole!="administrator"&&u.ActiveRole!="dispatcher"{errJSON(w,403,"forbidden","role cannot perform this action");return false};return true}
