func (a *App) createRequest(w http.ResponseWriter,r *http.Request,pre bool){u,role,ok:=requireAuth(a,w,r);if !ok{return};m,e:=jsonBody(r);if e!=nil{errJSON(w,400,"invalid_json","invalid JSON");return};if str(m,"originType")=="home"&&pre{errJSON(w,400,"invalid_origin_type","pre-sealed origin cannot be home");return};a.mu.Lock();yes,reason,lab,arrival:=a.service(m);typ:=a.sampleType(str(m,"sampleTypeId"));if typ==nil{a.mu.Unlock();errJSON(w,404,"not_found","sample type not found");return};rid,sid:=uuid(),uuid();s:=&Sample{ID:sid,RequestID:rid,RequesterID:u.ID,TypeID:typ.ID,Status:"sealed",OriginType:str(m,"originType"),Origin:coord(m),RequestedAt:str(m,"requestedAt"),Deadline:str(m,"deliveryDeadline"),Earliest:str(m,"earliestCollectionAt"),Latest:str(m,"latestCollectionAt"),Container:str(m,"containerType"),Tmin:num(m,"temperatureMinC"),Tmax:num(m,"temperatureMaxC"),Incompatible:idarr(m,"incompatibleSampleTypes"),Sealed:pre,Timeline:[]map[string]any{},Location:coord(m)};if s.OriginType==""{s.OriginType="home"};if s.Earliest==""{s.Earliest=s.RequestedAt};if s.Latest==""{s.Latest=s.RequestedAt};if yes{ s.Status="collection_offered";s.TargetLabID=lab.ID; var from *Location;for _,l:=range a.state.Locations{if l.Active&&l.Functions["collection_point"]&&distance(s.Origin,l.Coordinate)<=l.CoverageKm{from=l;break}};j:=a.createJourney(s,from,lab,!pre);_ = j};a.addTimeline(s,u.ID,role,"request_created",map[string]any{"serviceable":yes});a.state.Samples[sid]=s;a.state.Requests[rid]=map[string]any{"requestId":rid,"sampleId":sid,"requesterId":u.ID,"origin":s.Origin,"originType":s.OriginType,"requestedAt":s.RequestedAt,"deliveryDeadline":s.Deadline,"sampleTypeId":s.TypeID,"serviceable":yes};a.saveLocked();a.mu.Unlock();out:=map[string]any{"requestId":rid,"sampleId":sid,"serviceability":map[bool]string{true:"serviceable",false:"unserviceable"}[yes],"activeAssignmentIds":s.ActiveAssignments,"earliestCollectionAt":s.Earliest,"latestCollectionAt":s.Latest,"originType":s.OriginType,"alre