func uuid() string { b:=make([]byte,16); if _,e:=rand.Read(b);e!=nil { return fmt.Sprintf("%d",time.Now().UnixNano()) }; b[6]=(b[6]&15)|64; b[8]=(b[8]&63)|128; return fmt.Sprintf("%08x-%04x-%04x-%04x-%012x",b[0:4],b[4:6],b[6:8],b[8:10],b[10:]) }
