func (a *App) collect(w http.ResponseWriter,r *http.Request){u,role,ok:=requireAuth(a,w,r);if !ok{return};m,e:=jsonBody(r);if e!=nil{errJSON(w,400,"invalid_json","invalid JSON");return};a.mu.Lock();s:=a.state.Samples[str(m,"sampleId")];as:=a.state.Assignments[str(m,"assignmentId")];if s==nil||as==nil{a.mu.Unlock();errJSON(w,404,"not_found","sample or assignment not found");return};if as.WorkerID!=u.ID{a.mu.Unlock();errJSON(w,403,"forbidden","not assigned");return};typ:=a.sampleType(s.TypeID);ct:=str(m,"containerType");temp:=num(m,"observedTemperatureC");compliant:=ct==typ.ContainerType&&temp>=typ.Tmin&&temp<=typ.Tmax;if !compliant{a.mu.Unlock();errJSON(w,400,"handling_noncompliant","handling outside required range");return};s.Sealed=true;s.Status="sealed";s.CurrentHolderID=u.ID;s.SealedAt=str(m,"collectedAt");if s.SealedAt==""{s.SealedAt=now()};as.Status="completed";a.addTimeline(s,u.ID,role,"sample_sealed",map[string]any{"containerType":ct,"temperature":temp});a.saveLocked();a.mu.Unlock();dataJSON(w,201,map[string]any{"sampleId":s.ID,"status":"sealed","currentHolderId":u.ID,"sealedAt":s.SealedAt,"handlingCompliant":true})}
func (a *App) initiateHandoff(w http.ResponseWriter,r *http.Request){u,role,ok:=requireAuth(a,w);if !ok{return};m,e:=jsonBody(r);if e!=nil{errJSON(w,400,"invalid_json","invalid JSON");return};a.mu.Lock();s:=a.state.Samples[str(m,"sampleId")];if s==nil{a.mu.Unlock();errJSON(w,404,"not_found","sample not found");return};if s.CurrentHolderID!=""&&s.CurrentHolderID!=u.ID{a.mu.Unlock();errJSON(w,403,"forbidden","not current holder");return};h:=&Handoff{ID:uuid(),SampleID:s.ID,SenderID:u.ID,ReceiverID:str(m,"receiverId"),Status:"pending",CreatedAt:str(m,"initiatedAt")};if h.CreatedAt==""{h.CreatedAt=now()};a.state.Handoffs[h.ID]=h;a.addTimeline(s,u.ID,role,"handoff_initiated",map[string]any{"handoffId":h.ID,"receiverId":h.ReceiverID});a.saveLocked();a.mu.Unlock();dataJSON(w,201,map[string]any{"handoffId":h.ID,"senderId":h.SenderID,"receiverId":h.ReceiverID,"currentHolderId":u.ID,"status":"pending"})}
func (a *App) confirmHandoff(w http.ResponseWriter,r *http.Request){u,role,ok:=requireAuth(a,w);if !ok{return};m,e:=jsonBody(r);if e!=nil{errJSON(w,400,"invalid_json","invalid JSON");return};a.mu.Lock();h:=a.state.Handoffs[str(m,"handoffId")];if h==nil{a.mu.Unlock();errJSON(w,404,"not_found","handoff not found");return};side:=str(m,"confirmationSide");if side=="sender"&&u.ID==h.SenderID{h.SenderConfirmed=true};if side=="receiver"&&u.ID==h.ReceiverID{h.ReceiverConfirmed=true};s:=a.state.Samples[h.SampleID];if h.SenderConfirmed&&h.ReceiverConfirmed{h.Status="confirmed";s.CurrentHolderID=h.ReceiverID;s.Status="in_transit";a.addTimeline(s,u.ID,role,"custody_transferred",map[string]any{"handoffId":h.ID,"from":h.SenderID,"to":h.ReceiverID})};a.saveLocked();v:=map[string]any{"handoffId":h.ID,"status":h.Status,"senderConfirmed":h.SenderConfirmed,"receiverConfirmed":h.ReceiverConfirmed,"currentHolderId":s.CurrentHolderID};a.mu.Unlock();dataJSON(w,201,v)}
func (a *App) checkpoint(w http.ResponseWriter,r *http.Request){u,role,ok:=requireAuth(a,w);if !ok{return};m,e:=jsonBody(r);if e!=nil{errJSON(w,400,"invalid_json","invalid JSON");return};a.mu.Lock();s:=a.state.Samples[str(m,"sampleId")];if s==nil{a.mu.Unlock();errJSON(w,404,"not_found","sample not found");return};t:=a.sampleType(s.TypeID);com:=str(m,"containerType")==t.ContainerType&&num(m,"observedTemperatureC")>=t.Tmin&&num(m,"observedTemperatureC")<=t.Tmax;if !com{s.Status="exception";s.Exception=map[string]any{"reason":"handling_noncompliant"}};a.addTimeline(s,u.ID,role,"handling_checkpoint",map[string]any{"compliant":com});a.saveLocked();a.mu.Unlock();dataJSON(w,201,map[string]any{"checkpointId":uuid(),"sampleId":s.ID,"compliant":com,"sampleStatus":s.Status})}
func (a *App) progress(w http.ResponseWriter,r *http.Request){u,role,ok:=requireAuth(a,w);if !ok{return};m,e:=jsonBody(r);if e!=nil{errJSON(w,400,"invalid_json","invalid JSON");return};a.mu.Lock();as:=a.state.Assignments[str(m,"assignmentId")];if as==nil{a.mu.Unlock();errJSON(w,404,"not_found","assignment not found");return};if as.WorkerID!=u.ID{a.mu.Unlock();errJSON(w,403,"forbidden","not assigned");return};as.Status=str(m,"status");s:=a.state.Samples[as.SampleID];if s!=nil{if as.Status=="picked_up"{s.Status="in_transit"};if as.Status=="delivered"{s.Status="at_laboratory"};a.addTimeline(s,u.ID,role,"assignment_progress",map[string]any{"status":as.Status})};a.saveLocked();a.mu.Unlock();dataJSON(w,201,map[string]any{"assignmentId":as.ID,"sampleId":as.SampleID,"status":as.Status})}
func (a *App) workerLocation(w http.ResponseWriter,r *http.Request){u,role,ok:=requireAuth(a,w);if !ok{return};m,e:=jsonBody(r);if e!=nil{errJSON(w,400,"invalid_json","invalid JSON");return};a.mu.Lock();as:=a.state.Assignments[str(m,"assignmentId")];if as==nil{a.mu.Unlock();errJSON(w,404,"not_found","assignment not found");return};if as.WorkerID!=u.ID{a.mu.Unlock();errJSON(w,403,"forbidden","not assigned");return};u.Location=coord(m);a.audit(u.ID,role,"worker_location_recorded","user",u.ID,true,map[string]any{"coordinate":u.Location});a.saveLocked();a.mu.Unlock();dataJSON(w,201,map[string]any{"assignmentId":as.ID,"coordinate":coord(m),"sequence":intval(m,"sequence"),"recordedAt":str(m,"recordedAt")})}

