	j.RouteMode = "batched"
	j.PlanVersion++
	a.audit(u.ID, role, "journeys_merged", "journey", j.ID, true, map[string]any{})
	a.saveLocked()
	v := a.journeyOut(j)
	a.mu.Unlock()
	dataJSON(w, 201, v)
}
func (a *App) disruption(w http.ResponseWriter, r *http.Request) {
	u, role, ok := requireAuth(a, w)
	if !ok || (!adminOnly(w, u) && u.ActiveRole != "dispatcher") {
		return
	}
	m, e := jsonBody(r)
	if e != nil {
		errJSON(w, 400, "invalid_json", "invalid JSON")
		return
	}
	a.mu.Lock()
	samples := []string{}
	for _, s := range a.state.Samples {
		samples = append(samples, s.ID)
		if s.Status != "received" {
			s.Status = "exception"
			s.Exception = map[string]any{"reason": str(m, "reason")}
		}
	}
	a.audit(u.ID, role, "disruption_reported", "disruption", str(m, "resourceId"), true, map[string]any{})
	a.saveLocked()
	a.mu.Unlock()
	dataJSON(w, 201, map[string]any{"disruptionId": uuid(), "affectedSampleIds": samples, "replacementPlanIds": []string{}, "replanStatus": "exception"})
}
func (a *App) snapshot(w http.ResponseWriter, r *http.Request) {
	u, _, ok := requireAuth(a, w)
	if !ok {
		return
	}
	a.mu.RLock()
	rs := []map[string]any{}
	for _, l := range a.state.Locations {
		if l.Active && l.Functions["collection_point"] {
			rs = append(rs, map[string]any{"locationId": l.ID, "name": l.Name, "latitude": num(l.Coordinate, "latitude"), "longitude": num(l.Coordinate, "longitude"), "coverageKm": l.CoverageKm})
		}
	}
	v := map[string]any{"version": a.state.ServiceVersion, "status": "complete", "computedAt": now(), "networkRevision": a.state.NetworkRevision, "regions": rs, "activeCollectionPointCount": len(rs)}
	a.mu.RUnlock()
	_ = u
	dataJSON(w, 200, v)
}
func (a *App) searchAudit(w http.ResponseWriter, r *http.Request) {
	u, _, ok := requireAuth(a, w)
	if !ok {
		return
	}
	m, e := jsonBody(r)
	if e != nil {
		errJSON(w, 400, "invalid_json", "invalid JSON")
		return
	}
	a.mu.RLock()
	entries := []map[string]any{}
	for _, x := range a.state.Audits {
		if q := str(m, "query"); q != "" && !strings.Contains(strings.ToLower(x.Action+x.EntityType+x.EntityID), strings.ToLower(q)) {
			continue
		}
		if id := str(m, "entityId"); id != "" && x.EntityID != id {
			continue
		}
		entries = append(entries, map[string]any{"auditId": x.ID, "actorId": x.ActorID, "role": x.Role, "actorRole": x.Role, "action": x.Action, "entityType": x.EntityType, "entityId": x.EntityID, "success": x.Success, "occurredAt": x.At, "details": x.Details})
	}
	order := str(m, "order")
	if order == "" {
		order = "newest_first"
	}
	if order == "newest_first" {
		sort.Slice(entries, func(i, j int) bool { return entries[i]["occurredAt"].(string) > entries[j]["occurredAt"].(string) })
	}
	off := intval(m, "offset")
	lim := intval(m, "limit")
	if lim <= 0 {
		lim = 50
	}
	total := len(entries)
	if off > total {
		off = total
	}
	end := off + lim
	if end > total {
		end = total
	}
	part := entries[off:end]
	a.mu.RUnlock()
	v := map[string]any{"entries": part, "total": total, "returned": len(part), "offset": off, "limit": lim, "order": order, "hasMore": end < total}
	if end < total {
		v["nextOffset"] = end
	}
	dataJSON(w, 200, v)
}

func (a *App) updateType(w http.ResponseWriter, r *http.Request) { a.createType(w, r, true) }
func (a *App) mainHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != "GET" && r.Method != "POST" {
		errJSON(w, 405, "method_not_allowed", "method not allowed")
		return
	}
	a.handle(w, r)
}
func main() {
	a := &App{file: os.Getenv("LAB_STATE_FILE")}
	if a.file == "" {
		a.file = "/workspace/data/state.json"
	}
	a.mu.Lock()
	a.load()
	a.mu.Unlock()
	log.Printf("lab logistics listening on 127.0.0.1:8080")
	srv := &http.Server{Addr: "127.0.0.1:8080", Handler: http.HandlerFunc(a.mainHandler), ReadHeaderTimeout: 10 * time.Second}
	if err := srv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
		log.Fatal(err)
	}
}

