		s.Status = "in_transit"
		a.addTimeline(s, u.ID, role, "custody_transferred", map[string]any{"handoffId": h.ID, "from": h.SenderID, "to": h.ReceiverID})
	}
	a.saveLocked()
	v := map[string]any{"handoffId": h.ID, "status": h.Status, "senderConfirmed": h.SenderConfirmed, "receiverConfirmed": h.ReceiverConfirmed, "currentHolderId": s.CurrentHolderID}
