func (a *App) searchAudit(w http.ResponseWriter, r *http.Request) {
	u, _, ok := requireAuth(a, w)
	if !ok {
		return
	}
	m, e := jsonBody(r)
	if e != nil {
		errJSON(w, 400, "invalid_json", "invalid JSON")
		return
	}
	a.mu.RLock()
	entries := []map[string]any{}
	for _, x := range a.state.Audits {
		if q := str(m, "query"); q != "" && !strings.Contains(strings.ToLower(x.Action+x.EntityType+x.EntityID), strings.ToLower(q)) {
			continue
		}
		if id := str(m, "entityId"); id != "" && x.EntityID != id {
			continue
		}
		entries = append(entries, map[string]any{"auditId": x.ID, "actorId": x.ActorID, "role": x.Role, "actorRole": x.Role, "action": x.Action, "entityType": x.EntityType, "entityId": x.EntityID, "success": x.Success, "occurredAt": x.At, "details": x.Details})
	}
	order := str(m, "order")
	if order == "" {
		order = "newest_first"
	}
	if order == "newest_first" {
		sort.Slice(entries, func(i, j int) bool { return entries[i]["occurredAt"].(string) > entries[j]["occurredAt"].(string) })
	}
	off := intval(m, "offset")
	lim := intval(m, "limit")
	if lim <= 0 {
		lim = 50
	}
	total := len(entries)
	if off > total {
		off = total
	}
	end := off + lim
	if end > total {
		end = total
	}
	part := entries[off:end]
	a.mu.RUnlock()
	v := map[string]any{"entries": part, "total": total, "returned": len(part), "offset": off, "limit": lim, "order": order, "hasMore": end < total}
	if end < total {
		v["nextOffset"] = end
	}
	dataJSON(w, 200, v)
}

func (a *App) updateType(w http.ResponseWriter, r *http.Request) { a.createType(w, r, true) }
func (a *App) mainHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != "GET" && r.Method != "POST" {
		errJSON(w, 405, "method_not_allowed", "method not allowed")
		return
	}
	a.handle(w, r)
}
func main() {
	a := &App{file: os.Getenv("LAB_STATE_FILE")}
	if a.file == "" {
		a.file = "/workspace/data/state.json"
	}
	a.mu.Lock()
	a.load()
	a.mu.Unlock()
	log.Printf("lab logistics listening on 127.0.0.1:8080")
