package main

import (
	"crypto/rand"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"log"
	"math"
	"net/http"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"sync"
	"time"
)

type User struct {
	ID, Username, PasswordHash, Email, FullName, Phone string
	Roles, Qualifications                              []string
	Certifications                                     []map[string]any
	Active                                             bool
	AssignedLocationID, ActiveRole                     string
	Available                                          bool
	CapacityUnits                                      int
	Location                                           map[string]any
	AssignmentCount                                    int
}
type Location struct {
	ID, Name                                           string
