func (a *App) check(w http.ResponseWriter, r *http.Request) {
	u, _, ok := requireAuth(a, w, r)
	if !ok {
		return
	}
	m, e := jsonBody(r)
	if e != nil {
		errJSON(w, 400, "invalid_json", "invalid JSON")
		return
	}
	if !validCoord(coord(m)) {
		errJSON(w, 400, "invalid_origin", "invalid origin")
		return
	}
	if !iso(str(m, "deliveryDeadline")).After(iso(str(m, "requestedAt"))) {
		errJSON(w, 400, "invalid_deadline", "invalid deadline")
		return
	}
	a.mu.RLock()
	yes, reason, lab, arrival := a.service(m)
	ver := a.state.ServiceVersion
	a.mu.RUnlock()
	out := map[string]any{"serviceable": yes, "reason": reason, "serviceabilityVersion": ver}
	if lab != nil {
		out["targetLaboratoryId"] = lab.ID
	}
	if arrival != "" {
		out["estimatedArrivalAt"] = arrival
	}
	a.mu.Lock()
	a.audit(u.ID, u.ActiveRole, "permission_check", "serviceability", strconv.Itoa(ver), true, map[string]any{"serviceable": yes})
	a.saveLocked()
	a.mu.Unlock()
	dataJSON(w, 200, out)
}

func (a *App) createRequest(w http.ResponseWriter, r *http.Request, pre bool) {
	u, role, ok := requireAuth(a, w, r)
	if !ok {
		return
	}
	m, e := jsonBody(r)
	if e != nil {
		errJSON(w, 400, "invalid_json", "invalid JSON")
		return
	}
	if str(m, "originType") == "home" && pre {
		errJSON(w, 400, "invalid_origin_type", "pre-sealed origin cannot be home")
		return
	}
	a.mu.Lock()
	yes, reason, lab, arrival := a.service(m)
	typ := a.sampleType(str(m, "sampleTypeId"))
	if typ == nil {
		a.mu.Unlock()
		errJSON(w, 404, "not_found", "sample type not found")
		return
	}
	rid, sid := uuid(), uuid()
	s := &Sample{ID: sid, RequestID: rid, RequesterID: u.ID, TypeID: typ.ID, Status: "sealed", OriginType: str(m, "originType"), Origin: coord(m), RequestedAt: str(m, "requestedAt"), Deadline: str(m, "deliveryDeadline"), Earliest: str(m, "earliestCollectionAt"), Latest: str(m, "latestCollectionAt"), Container: str(m, "containerType"), Tmin: num(m, "temperatureMinC"), Tmax: num(m, "temperatureMaxC"), Incompatible: idarr(m, "incompatibleSampleTypes"), Sealed: pre, Timeline: []map[string]any{}, Location: coord(m)}
	if s.OriginType == "" {
		s.OriginType = "home"
	}
	if s.Earliest == "" {
		s.Earliest = s.RequestedAt
	}
	if s.Latest == "" {
		s.Latest = s.RequestedAt
	}
	if yes {
		s.Status = "collection_offered"
		s.TargetLabID = lab.ID
		var from *Location
		for _, l := range a.state.Locations {
			if l.Active && l.Functions["collection_point"] && distance(s.Origin, l.Coordinate) <= l.CoverageKm {
				from = l
				break
			}
		}
		j := a.createJourney(s, from, lab, !pre)
		_ = j
	}
	a.addTimeline(s, u.ID, role, "request_created", map[string]any{"serviceable": yes})
	a.state.Samples[sid] = s
	a.state.Requests[rid] = map[string]any{"requestId": rid, "sampleId": sid, "requesterId": u.ID, "origin": s.Origin, "originType": s.OriginType, "requestedAt": s.RequestedAt, "deliveryDeadline": s.Deadline, "sampleTypeId": s.TypeID, "serviceable": yes}
	a.saveLocked()
	a.mu.Unlock()
	out := map[string]any{"requestId": rid, "sampleId": sid, "serviceability": map[bool]string{true: "serviceable", false: "unserviceable"}[yes], "activeAssignmentIds": s.ActiveAssignments, "earliestCollectionAt": s.Earliest, "latestCollectionAt": s.Latest, "originType": s.OriginType, "alreadySealed": pre}
	if reason != "serviceable" {
		out["serviceabilityReason"] = reason
	}
	if lab != nil {
		out["targetLaboratoryId"] = lab.ID
	}
	if s.JourneyID != "" {
		out["journeyId"] = s.JourneyID
	}
	dataJSON(w, 201, out)
}

func (a *App) createLocation(w http.ResponseWriter, r *http.Request, update bool) {
	u, role, ok := requireAuth(a, w, r)
	if !ok || !adminOnly(w, u) {
		return
	}
	m, e := jsonBody(r)
	if e != nil {
		errJSON(w, 400, "invalid_json", "invalid JSON")
		return
	}
	if !validCoord(coord(m)) {
		errJSON(w, 400, "invalid_coordinate", "invalid coordinate")
		return
	}
	a.mu.Lock()
	var l *Location
	if update {
		l = a.state.Locations[str(m, "locationId")]
		if l == nil {
			a.mu.Unlock()
			errJSON(w, 404, "not_found", "location not found")
			return
		}
	} else {
		l = &Location{ID: uuid(), Accepted: map[string]bool{}}
		a.state.Locations[l.ID] = l
	}
	l.Name = str(m, "name")
	l.Coordinate = coord(m)
	l.CoverageKm = num(m, "coverageKm")
	if l.CoverageKm <= 0 {
		l.CoverageKm = 5
	}
	l.HandlingMinutes = intval(m, "handlingMinutes")
	l.Active = boolv(m, "active", true)
	if fs, ok := m["functions"].([]any); ok {
		l.Functions = map[string]bool{}
		for _, x := range fs {
			if s, ok := x.(string); ok {
				l.Functions[s] = true
			}
		}
