		item := map[string]any{"kind": x.Kind, "assignmentId": x.ID, "sampleId": x.SampleID, "status": x.Status, "journeyId": x.JourneyID, "fromLocationId": x.From, "toLocationId": x.To, "sequence": x.Sequence, "history": x.History}
		bucket := "pending"
		if x.Status == "accepted" || x.Status == "in_progress" {
			bucket = "inProgress"
		}
		if x.Status == "completed" || x.Status == "delivered" {
			bucket = "completed"
		}
		v[bucket] = append(v[bucket].([]any), item)
	}
	for _, s := range a.state.Samples {
		if s.RequesterID == u.ID || role == "administrator" || role == "dispatcher" {
			item := map[string]any{"kind": "sample", "sampleId": s.ID, "requestId": s.RequestID, "status": s.Status, "history": s.Timeline, "locationStale": s.LocationAt == ""}
			bucket := "pending"
			if s.Status == "received" {
				bucket = "completed"
