func (a *App) configureCapacity(w http.ResponseWriter, r *http.Request) {
	u, role, ok := requireAuth(a, w, r)
	if !ok || !adminOnly(w, u) {
		return
	}
	m, e := jsonBody(r)
	if e != nil {
		errJSON(w, 400, "invalid_json", "invalid JSON")
		return
	}
	if intval(m, "capacityUnits") < 0 || intval(m, "cooledCapacityUnits") < 0 {
		errJSON(w, 400, "invalid_capacity", "invalid capacity")
		return
	}
	a.mu.Lock()
	if l := a.state.Locations[str(m, "resourceId")]; l != nil {
		if l.Capacity-l.Reserved < intval(m, "capacityUnits") {
			a.mu.Unlock()
			errJSON(w, 409, "capacity_reserved", "reserved capacity")
			return
		}
		l.Capacity = intval(m, "capacityUnits")
		l.CooledCapacity = intval(m, "cooledCapacityUnits")
		a.audit(u.ID, role, "capacity_configured", "location", l.ID, true, map[string]any{})
		a.saveLocked()
		out := capOut(l)
		a.mu.Unlock()
		dataJSON(w, 200, out)
		return
	}
	if c := a.state.Connections[str(m, "resourceId")]; c != nil {
		c.Capacity = intval(m, "capacityUnits")
		c.CooledCapacity = intval(m, "cooledCapacityUnits")
		a.saveLocked()
		a.mu.Unlock()
		dataJSON(w, 200, map[string]any{"resourceId": c.ID, "capacityUnits": c.Capacity, "cooledCapacityUnits": c.CooledCapacity})
		return
	}
	a.mu.Unlock()
	errJSON(w, 404, "not_found", "resource not found")
}
