	if s.CurrentHolderID != "" {
		v["currentHolderId"] = s.CurrentHolderID
	}
	if s.Location != nil {
		v["latestLocation"] = s.Location
	}
	if s.LocationAt != "" {
		v["locationRecordedAt"] = s.LocationAt
	}
	if s.Exception != nil {
