	}
	off := intval(m, "offset")
	lim := intval(m, "limit")
	if lim <= 0 {
		lim = 50
	}
	total := len(entries)
	if off > total {
		off = total
	}
	end := off + lim
	if end > total {
		end = total
	}
	part := entries[off:end]
	a.mu.RUnlock()
	v := map[string]any{"entries": part, "total": total, "returned": len(part), "offset": off, "limit": lim, "order": order, "hasMore": end < total}
