func (a *App) operationsLocked(u *User) map[string]any {
	v := map[string]any{"samples": []any{}, "workers": []any{}, "locations": []any{}, "connections": []any{}, "routes": []any{}, "handoffs": []any{}, "delays": []any{}, "exceptions": []any{}, "assignmentCountSpread": 0, "ineligibleAssignmentCount": 0}
	ss := []any{}
	for _, s := range a.state.Samples {
		ss = append(ss, map[string]any{"sampleId": s.ID, "status": s.Status, "requestId": s.RequestID, "origin": s.Origin, "deliveryDeadline": s.Deadline, "currentHolderId": s.CurrentHolderID, "activeJourneyId": s.JourneyID, "latestLocation": s.Location, "locationRecordedAt": s.LocationAt, "locationStale": s.LocationAt == ""})
	}
	v["samples"] = ss
	ws := []any{}
	min, max := 999999, 0
	for _, x := range a.state.Users {
		if !x.Active || x.ID == u.ID && u.ActiveRole == "requester" {
			continue
		}
		if x.AssignmentCount < min {
			min = x.AssignmentCount
		}
		if x.AssignmentCount > max {
			max = x.AssignmentCount
		}
		ws = append(ws, map[string]any{"workerId": x.ID, "fullName": x.FullName, "roles": x.Roles, "available": x.Available, "status": map[bool]string{true: "available", false: "unavailable"}[x.Available], "capacityUnits": x.CapacityUnits, "assignmentCount": x.AssignmentCount, "latestLocation": x.Location, "locationRecordedAt": "", "locationStale": x.Location == nil})
	}
	v["workers"] = ws
	if min == 999999 {
		min = 0
	}
	v["assignmentCountSpread"] = max - min
	ls := []any{}
	for _, l := range a.state.Locations {
		ls = append(ls, map[string]any{"id": l.ID, "locationId": l.ID, "name": l.Name, "coordinate": l.Coordinate, "active": l.Active, "coverageKm": l.CoverageKm, "handlingMinutes": l.HandlingMinutes, "functions": l.Functions, "capacity": a.capacity(l), "acceptedSampleTypeIds": acceptedIds(l)})
	}
	v["locations"] = ls
	cs := []any{}
	for _, c := range a.state.Connections {
		cs = append(cs, map[string]any{"id": c.ID, "connectionId": c.ID, "fromLocationId": c.From, "toLocationId": c.To, "travelMinutes": c.Travel, "costUnits": c.Cost, "cooled": c.Cooled, "active": c.Active, "capacity": map[string]any{"capacityUnits": c.Capacity, "reservedUnits": c.Reserved, "availableUnits": c.Capacity - c.Reserved, "cooledCapacityUnits": c.CooledCapacity, "cooledReservedUnits": c.CooledReserved, "cooledAvailableUnits": c.CooledCapacity - c.CooledReserved}})
	}
	v["connections"] = cs
	return v
}
