func (a *App) assign(w http.ResponseWriter, r *http.Request, accept bool) {
	u, role, ok := requireAuth(a, w, r)
	if !ok {
		return
	}
	m, e := jsonBody(r)
	if e != nil {
		errJSON(w, 400, "invalid_json", "invalid JSON")
		return
	}
	id := str(m, "assignmentId")
	a.mu.Lock()
	as := a.state.Assignments[id]
	if as == nil {
		a.mu.Unlock()
		errJSON(w, 404, "not_found", "assignment not found")
		return
	}
	if as.WorkerID != u.ID {
		a.mu.Unlock()
		errJSON(w, 403, "forbidden", "assignment was offered to another worker")
		return
	}
	if accept {
		as.Status = "accepted"
		a.audit(u.ID, role, "assignment_accepted", "assignment", id, true, map[string]any{})
		a.saveLocked()
		a.mu.Unlock()
		dataJSON(w, 201, map[string]any{"assignmentId": id, "workerId": u.ID, "status": "accepted"})
	} else {
		as.Status = "pending"
		s := a.state.Samples[as.SampleID]
		reoffer := ""
		if s != nil {
			a.assignWorker(as, role, s)
			reoffer = as.WorkerID
		}
		a.audit(u.ID, role, "assignment_declined", "assignment", id, true, map[string]any{})
		a.saveLocked()
		a.mu.Unlock()
		v := map[string]any{"assignmentId": id, "status": "pending", "declinedBy": u.ID, "declinedAt": str(m, "declinedAt")}
		if v["declinedAt"] == "" {
			v["declinedAt"] = now()
		}
		if reoffer != "" {
			v["reofferedTo"] = reoffer
		}
		dataJSON(w, 201, v)
	}
}
func (a *App) accept(w http.ResponseWriter, r *http.Request)  { a.assign(w, r, true) }
func (a *App) decline(w http.ResponseWriter, r *http.Request) { a.assign(w, r, false) }
func (a *App) collect(w http.ResponseWriter, r *http.Request) {
	u, role, ok := requireAuth(a, w, r)
	if !ok {
		return
	}
	m, e := jsonBody(r)
	if e != nil {
		errJSON(w, 400, "invalid_json", "invalid JSON")
		return
	}
	a.mu.Lock()
	s := a.state.Samples[str(m, "sampleId")]
	as := a.state.Assignments[str(m, "assignmentId")]
	if s == nil || as == nil {
		a.mu.Unlock()
		errJSON(w, 404, "not_found", "sample or assignment not found")
		return
	}
	if as.WorkerID != u.ID {
		a.mu.Unlock()
		errJSON(w, 403, "forbidden", "not assigned")
		return
	}
	typ := a.sampleType(s.TypeID)
	ct := str(m, "containerType")
	temp := num(m, "observedTemperatureC")
	compliant := ct == typ.ContainerType && temp >= typ.Tmin && temp <= typ.Tmax
	if !compliant {
		a.mu.Unlock()
		errJSON(w, 400, "handling_noncompliant", "handling outside required range")
		return
	}
	s.Sealed = true
	s.Status = "sealed"
	s.CurrentHolderID = u.ID
	s.SealedAt = str(m, "collectedAt")
	if s.SealedAt == "" {
		s.SealedAt = now()
	}
	as.Status = "completed"
	a.addTimeline(s, u.ID, role, "sample_sealed", map[string]any{"containerType": ct, "temperature": temp})
	a.saveLocked()
	a.mu.Unlock()
	dataJSON(w, 201, map[string]any{"sampleId": s.ID, "status": "sealed", "currentHolderId": u.ID, "sealedAt": s.SealedAt, "handlingCompliant": true})
}
