		a.mu.Unlock()
		errJSON(w, 404, "not_found", "handoff not found")
		return
	}
	side := str(m, "confirmationSide")
	if side == "sender" && u.ID == h.SenderID {
		h.SenderConfirmed = true
	}
	if side == "receiver" && u.ID == h.ReceiverID {
