	a.saveLocked()
	a.mu.Unlock()
	dataJSON(w, 201, map[string]any{"exceptionId": uuid(), "sampleId": s.ID, "status": "exception", "reason": str(m, "reason")})
}
func (a *App) journeyOut(j *Journey) map[string]any {
	return map[string]any{"journeyId": j.ID, "planVersion": j.PlanVersion, "routeMode": j.RouteMode, "status": j.Status, "estimatedDeliveryAt": j.EstimatedDelivery, "totalCostUnits": j.Cost, "capacityUsed": j.CapacityUsed, "capacityAvailable": j.CapacityAvailable, "sampleIds": j.SampleIDs, "orderedStops": j.Stops, "legs": j.Legs, "assignedWorkerIds": j.AssignmentIDs}
}
func (a *App) readJourney(w http.ResponseWriter, r *http.Request) {
	u, _, ok := requireAuth(a, w, r)
	if !ok {
		return
	}
	m, e := jsonBody(r)
	if e != nil {
		errJSON(w, 400, "invalid_json", "invalid JSON")
