func (a *App) journeyView(j *Journey, u *User) map[string]any {
	if u.ActiveRole == "requester" {
		return map[string]any{"journeyId": j.ID, "sampleIds": j.SampleIDs, "legs": j.Legs, "orderedStops": j.Stops, "status": j.Status, "planVersion": j.PlanVersion, "routeMode": j.RouteMode, "estimatedDeliveryAt": j.EstimatedDelivery}
	}
