func (a *App) roleWork(w http.ResponseWriter, r *http.Request) {
	u, role, ok := requireAuth(a, w, r)
	if !ok {
		return
	}
	m, e := jsonBody(r)
	if e != nil {
		errJSON(w, 400, "invalid_json", "invalid JSON")
		return
	}
	if q := str(m, "role"); q != "" && !contains(u.Roles, q) {
		errJSON(w, 403, "forbidden", "role not assigned")
		return
	}
	a.mu.RLock()
	v := map[string]any{"pending": []any{}, "inProgress": []any{}, "completed": []any{}}
	for _, x := range a.state.Assignments {
		if x.WorkerID != u.ID && role != "administrator" && role != "dispatcher" {
			continue
		}
		item := map[string]any{"kind": x.Kind, "assignmentId": x.ID, "sampleId": x.SampleID, "status": x.Status, "journeyId": x.JourneyID, "fromLocationId": x.From, "toLocationId": x.To, "sequence": x.Sequence, "history": x.History}
		bucket := "pending"
		if x.Status == "accepted" || x.Status == "in_progress" {
			bucket = "inProgress"
		}
		if x.Status == "completed" || x.Status == "delivered" {
			bucket = "completed"
		}
		v[bucket] = append(v[bucket].([]any), item)
	}
	for _, s := range a.state.Samples {
		if s.RequesterID == u.ID || role == "administrator" || role == "dispatcher" {
			item := map[string]any{"kind": "sample", "sampleId": s.ID, "requestId": s.RequestID, "status": s.Status, "history": s.Timeline, "locationStale": s.LocationAt == ""}
			bucket := "pending"
			if s.Status == "received" {
				bucket = "completed"
			}
			v[bucket] = append(v[bucket].([]any), item)
		}
	}
	a.mu.RUnlock()
	dataJSON(w, 200, v)
}
func (a *App) readPlanAction(w http.ResponseWriter, r *http.Request, action string) {
	u, role, ok := requireAuth(a, w, r)
	if !ok {
		return
	}
	m, e := jsonBody(r)
	if e != nil {
		errJSON(w, 400, "invalid_json", "invalid JSON")
		return
	}
	a.mu.Lock()
	id := str(m, "journeyId")
	if action == "merge" {
		id = str(m, "targetJourneyId")
	}
	j := a.state.Journeys[id]
	if j == nil {
		a.mu.Unlock()
		errJSON(w, 404, "not_found", "journey not found")
		return
	}
	expected := intval(m, "expectedPlanVersion")
	if expected > 0 && expected != j.PlanVersion {
		a.mu.Unlock()
		errJSON(w, 409, "stale_plan", "plan version is stale")
		return
	}
	if action == "cancel" {
		j.Status = "cancelled"
		for _, sid := range j.SampleIDs {
			if s := a.state.Samples[sid]; s != nil {
				s.Status = "cancelled"
			}
		}
	}
	if action != "cancel" {
		j.PlanVersion++
		j.ReplanStatus = "replaced"
	}
	a.audit(u.ID, role, action, "journey", j.ID, true, map[string]any{"planVersion": j.PlanVersion})
	a.saveLocked()
	v := a.journeyOut(j)
	a.mu.Unlock()
	dataJSON(w, 201, v)
}
func (a *App) cancel(w http.ResponseWriter, r *http.Request) { a.readPlanAction(w, r, "cancelled") }
