(() => {
  const root = document.getElementById('app');
  let token = localStorage.getItem('sessionToken') || '', user = null, bootstrap = null, busy = false;
  const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
  async function api(path, body, method='POST') {
    const res = await fetch('/api'+path, {method, headers:{'Content-Type':'application/json', ...(token?{'Authorization':'Bearer '+token}:{})}, body: body===undefined?undefined:JSON.stringify(body)});
    const data = await res.json().catch(()=>({})); if (!res.ok) throw new Error(data.message || data.error || 'Request failed'); return data;
  }
  function login(){root.innerHTML=`<main class="login"><section class="login-card"><div class="mark">SN</div><p class="eyebrow">CLINICAL LOGISTICS CONTROL</p><h1>Specimen Network</h1><p class="muted">Secure pickup, custody, and delivery operations.</p><form id="login"><label>Username<input name="username" autocomplete="username" required></label><label>Password<input name="password" type="password" autocomplete="current-password" required></label><button>Sign in securely</button><p id="login-error" class="error"></p></form><p class="hint">The administrator account is provisioned from <code>ADMIN_USERNAME</code> and <code>ADMIN_PASSWORD</code>.</p></section></main>`; document.getElementById('login').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target);try{let x=await api('/authenticate-user',Object.fromEntries(f));token=x.sessionToken;localStorage.setItem('sessionToken',token);await load();}catch(x){document.getElementById('login-error').textContent=x.message}}}
  async function load(){try{bootstrap=await api('/ui/bootstrap',{});user=bootstrap.user;render()}catch(e){token='';localStorage.removeItem('sessionToken');login()}}
  const roles = () => (user?.roles||[]).map(r=>`<option value="${esc(r)}" ${r===user.activeRole?'selected':''}>${esc(r.replaceAll('_',' '))}</option>`).join('');
  function render(){root.innerHTML=`<div class="app"><aside><div class="brand"><div class="mark small">SN</div><div><strong>Specimen<br>Network</strong><span>OPERATIONS</span></div></div><nav><button class="nav active" data-page="overview">Overview</button><button class="nav" data-page="requests">Requests</button><button class="nav" data-page="samples">Samples & custody</button><button class="nav" data-page="network">Network map</button><button class="nav" data-page="audit">Audit trail</button></nav><div class="side-foot"><span class="pulse"></span> Network operational<br><small>Version ${esc(bootstrap.serviceability?.version||1)}</small></div></aside><section class="main"><header><div><span class="eyebrow">CONTROL ROOM / TODAY</span><h2 id="page-title">Overview</h2></div><div class="header-actions"><label class="role">Working as <select id="role">${roles()}</select></label><span class="avatar">${esc((user?.username||'A')[0].toUpperCase())}</span><button class="logout" id="logout">Sign out</button></div></header><div id="content"></div></section></div>`;document.getElementById('role').onchange=async e=>{try{let x=await api('/select-active-role',{role:e.target.value});user.activeRole=x.activeRole;render()}catch(x){alert(x.message)}};document.getElementById('logout').onclick=()=>{token='';localStorage.removeItem('sessionToken');login()};document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>{document.querySelectorAll('.nav').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.getElementById('page-title').textContent=b.textContent;pages[b.dataset.page]()});pages.overview()}
  const stat=(label,value,detail,kind='')=>`<article class="stat ${kind}"><span>${label}</span><strong>${value}</strong><small>${detail}</small></article>`;
