  const pages={overview:async()=>{let x=await api('/read-operations-state',{}).catch(()=>({}));let s=x.summary||x;document.getElementById('content').innerHTML=`<div class="welcome"><div><p class="eyebrow">GOOD MORNING, ${esc(user.username).toUpperCase()}</p><h1>Operations at a glance</h1><p class="muted">Track every specimen from collection to laboratory receipt.</p></div><button class="primary" onclick="window.newRequest()">＋ New collection request</button></div><div class="stats">${stat('Active samples',s.activeSamples||0,'Across all journeys','blue')}${stat('Awaiting custody',s.awaitingHandoffs||0,'Handoffs needing confirmation','amber')}${stat('At risk',s.atRiskSamples||0,'Deadlines in the next 2 hours','red')}${stat('Today received',s.receivedToday||0,'Successfully completed','green')}</div><div class="grid-two"><section class="panel"><div class="panel-head"><div><span class="eyebrow">SERVICEABILITY</span><h3>Network coverage</h3></div><span class="tag green">LIVE</span></div><div class="coverage"><div class="ring"><b>${bootstrap.serviceability?.activeCollectionPointCount||0}</b><small>active nodes</small></div><div><strong>Serviceability version ${bootstrap.serviceability?.version||1}</strong><p class="muted">All requests are checked against the last complete network calculation.</p></div></div></section><section class="panel"><div class="panel-head"><div><span class="eyebrow">CAPACITY SIGNALS</span><h3>Network readiness</h3></div></div><div class="bar-row"><span>Regular capacity</span><b>Available</b><i><em style="width:72%"></em></i></div><div class="bar-row"><span>Cooled capacity</span><b>Available</b><i><em class="cool" style="width:48%"></em></i></div><p class="muted micro">Capacity is reserved at journey creation and released on completion.</p></section></div><section class="panel activity"><div class="panel-head"><div><span class="eyebrow">WORK QUEUE</span><h3>Recent activity</h3></div><button class="text-button" onclick="pages.requests()">View all →</button></div>${empty('Your queue is clear','New offers and custody events will appear here.')}</section>`},
    requests:()=>{document.getElementById('content').innerHTML=`<div class="welcome"><div><p class="eyebrow">REQUEST MANAGEMENT</p><h1>Collection requests</h1><p class="muted">Check serviceability before committing a new request.</p></div><button class="primary" onclick="window.newRequest()">＋ New request</button></div><section class="panel"><div class="tabs"><button class="tab selected">All requests</button><button class="tab">In progress</button><button class="tab">Completed</button></div>${empty('No requests yet','Create a request after confirming location, sample type, and deadline.')}</section>`},
    samples:async()=>{let id=prompt('Enter a sample ID to view its lifecycle (optional)');if(id){try{let x=await api('/read-sample-state/'+encodeURIComponent(id),{});document.getElementById('content').innerHTML=`<section class="panel"><p class="eyebrow">SAMPLE LIFECYCLE</p><h1>${esc(x.sample?.sampleId||id)}</h1><div class="timeline">${(x.timeline||[]).map(t=>`<div><b>${esc(t.event||t.status)}</b><small>${esc(t.occurredAt||'')}</small></div>`).join('')||'No timeline events'}</div></section>`}catch(e){alert(e.message)}}else document.getElementById('content').innerHTML=`<div class="welcome"><div><p class="eyebrow">CHAIN OF CUSTODY</p><h1>Samples & custody</h1><p class="muted">Every sealed sample has one accountable custodian.</p></div></div><section class="panel">${empty('Search a sample','Use the sample ID to see location, holder, route progress, and timeline.')}</section>`},
    network:()=>document.getElementById('content').innerHTML=`<div class="welcome"><div><p class="eyebrow">LIVE NETWORK</p><h1>Nodes & routes</h1><p class="muted">Current locations and route readiness across your operating network.</p></div><span class="tag green">● LIVE</span></div><section class="map"><div class="map-grid"></div><div class="map-label lab">LAB · ACTIVE</div><div class="map-label hub">HUB · ACTIVE</div><div class="map-label home">COLLECTION POINT</div><div class="map-legend"><b>Network map</b><span><i class="dot blue"></i> Node</span><span><i class="dot green-dot"></i> Laboratory</span><small>Local PMTiles assets supported</small></div></section>`,
    audit:()=>document.getElementById('content').innerHTML=`<div class="welcome"><div><p class="eyebrow">GOVERNANCE</p><h1>Audit trail</h1><p class="muted">Search immutable actions, custody, capacity, and permission decisions.</p></div></div><section class="panel"><form id="audit-form" class="search"><input name="query" placeholder="Search action, sample, or request ID"><button class="secondary">Search audit</button></form><div id="audit-results" class="audit-results">Enter a search term or search all events.</div></section>`+(()=>{setTimeout(()=>document.getElementById('audit-form').onsubmit=async e=>{e.preventDefault();let q=Object.fromEntries(new FormData(e.target));try{let x=await api('/search-audit-trail',q);document.getElementById('audit-results').innerHTML=(x.entries||[]).map(a=>`<div class="audit-row"><b>${esc(a.action)}</b><span>${esc(a.entityType)} · ${esc(a.entityId)}</span><time>${esc(a.occurredAt)}</time></div>`).join('')||'No matching events'}catch(x){alert(x.message)}})},0),''})()};
  window.newRequest=()=>{let type=prompt('Sample type (Amber, Indigo, Frost, Pulse)','Amber');if(!type)return;alert('Use the API serviceability check to validate the collection window and delivery deadline before creating the request.')};
  if(token)load();else login();
})();

