action.file_text:
import { useEffect, useState } from 'react';

type Role = 'requester' | 'certified_collection_professional' | 'relay_courier' | 'node_handler' | 'laboratory_intake_operator' | 'dispatcher' | 'administrator';
type User = { userId: string; username: string; roles: Role[]; activeRole: Role | '' };
type Bootstrap = { user: User; serviceability: { version: number; activeCollectionPointCount: number } };

const api = async <T,>(path: string, body: unknown = {}): Promise<T> => {
  const token = localStorage.getItem('sessionToken') ?? '';
  const response = await fetch(`/api${path}`, { method: 'POST', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` }, body: JSON.stringify(body) });
  if (!response.ok) throw new Error((await response.json()).message ?? 'Request failed');
  return response.json() as Promise<T>;
};

export default function App() {
  const [session, setSession] = useState<Bootstrap | null>(null);
  const [page, setPage] = useState('Overview');
  useEffect(() => { api<Bootstrap>('/ui/bootstrap').then(setSession).catch(() => localStorage.removeItem('sessionToken')); }, []);
  if (!session) return <div className="login"><div className="login-card"><h1>Specimen Network</h1><p>Sign in to the clinical logistics control room.</p></div></div>;
  const switchRole = async (role: Role) => { const result = await api<{ activeRole: Role }>('/select-active-role', { role }); setSession({ ...session, user: { ...session.user, activeRole: result.activeRole } }); };
  return <div className="app"><aside><strong>Specimen Network</strong>{['Overview', 'Requests', 'Samples & custody', 'Network map', 'Audit trail'].map(item => <button className={item === page ? 'nav active' : 'nav'} onClick={() => setPage(item)} key={item}>{item}</button>)}</aside><main><header><h2>{page}</h2><label>Working as <select value={session.user.activeRole} onChange={e => switchRole(e.target.value as Role)}>{session.user.roles.map(role => <option key={role}>{role}</option>)}</select></label></header><section><p className="eyebrow">CONTROL ROOM / {session.user.username.toUpperCase()}</p><h1>{page}</h1><p className="muted">Role-scoped work, custody, routes, and immutable history.</p></section></main></div>;
}

