func (a *App) createType(w http.ResponseWriter, r *http.Request, update bool) {
	u, role, ok := requireAuth(a, w, r)
	if !ok || !adminOnly(w, u) {
		return
	}
	m, e := jsonBody(r)
	if e != nil {
		errJSON(w, 400, "invalid_json", "invalid JSON")
		return
	}
	if str(m, "containerType") == "" || num(m, "temperatureMaxC") < num(m, "temperatureMinC") {
		errJSON(w, 400, "invalid_handling_rule", "invalid handling rule")
		return
	}
	a.mu.Lock()
	var t *SampleType
	if update {
		t = a.state.SampleTypes[str(m, "sampleTypeId")]
		if t == nil {
			a.mu.Unlock()
			errJSON(w, 404, "not_found", "sample type not found")
			return
		}
	} else {
		t = &SampleType{ID: uuid(), Name: str(m, "name")}
		a.state.SampleTypes[t.ID] = t
	}
	t.Qualified = boolv(m, "qualifiedCollectorRequired", true)
	t.RequiredQualification = str(m, "requiredQualification")
	t.ContainerType = str(m, "containerType")
	t.Tmin = num(m, "temperatureMinC")
	t.Tmax = num(m, "temperatureMaxC")
