		}
		if x.AssignmentCount > max {
			max = x.AssignmentCount
		}
		ws = append(ws, map[string]any{"workerId": x.ID, "fullName": x.FullName, "roles": x.Roles, "available": x.Available, "status": map[bool]string{true: "available", false: "unavailable"}[x.Available], "capacityUnits": x.CapacityUnits, "assignmentCount": x.AssignmentCount, "latestLocation": x.Location, "locationRecordedAt": "", "locationStale": x.Location == nil})
	}
	v["workers"] = ws
	if min == 999999 {
		min = 0
	}
	v["assignmentCountSpread"] = max - min
	ls := []any{}
	for _, l := range a.state.Locations {
		ls = append(ls, map[string]any{"id": l.ID, "locationId": l.ID, "name": l.Name, "coordinate": l.Coordinate, "active": l.Active, "coverageKm": l.CoverageKm, "handlingMinutes": l.HandlingMinutes, "functions": l.Functions, "capacity": a.capacity(l), "acceptedSampleTypeIds": acceptedIds(l)})
