package main

import (
	"crypto/rand"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"log"
	"math"
	"net/http"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"sync"
	"time"
)

type User struct {
	ID, Username, PasswordHash, Email, FullName, Phone string
	Roles, Qualifications                              []string
	Certifications                                     []map[string]any
	Active                                             bool
	AssignedLocationID, ActiveRole                     string
	Available                                          bool
	CapacityUnits                                      int
	Location                                           map[string]any
	AssignmentCount                                    int
}
type Location struct {
	ID, Name                                           string
	Coordinate                                         map[string]any
	CoverageKm                                         float64
	HandlingMinutes                                    int
	Active                                             bool
	Functions                                          map[string]bool
	Capacity, CooledCapacity, Reserved, CooledReserved int
	Accepted                                           map[string]bool
}
type Connection struct {
	ID, From, To                                       string
	Travel                                             int
	Cost                                               float64
	Cooled, Active                                     bool
	Capacity, CooledCapacity, Reserved, CooledReserved int
}
type SampleType struct {
	ID, Name, RequiredQualification, ContainerType string
	Qualified, Cooled, Batching                    bool
	Tmin, Tmax                                     float64
	Incompatible                                   []string
}
type Sample struct {
	ID, RequestID, RequesterID, JourneyID, TypeID, Status, OriginType, CurrentHolderID, TargetLabID string
	Origin                                                                                          map[string]any
	RequestedAt, Deadline, Earliest, Latest, SealedAt, LocationAt                                   string
	Container                                                                                       string
	Tmin, Tmax                                                                                      float64
	Incompatible                                                                                    []string
	Sealed                                                                                          bool
	Exception                                                                                       map[string]any
	Timeline                                                                                        []map[string]any
	ActiveAssignments                                                                               []string
	Location                                                                                        map[string]any
}
type Journey struct {
	ID                              string
	PlanVersion                     int
	RouteMode, Status               string
	EstimatedDelivery               string
	Cost                            float64
	CapacityUsed, CapacityAvailable int
	SampleIDs                       []string
	Stops                           []map[string]any
	Legs                            []map[string]any
	AssignmentIDs                   []string
	ParentID                        string
	ReplanStatus                    string
}
type Assignment struct {
	ID, Kind, SampleID, JourneyID, From, To, WorkerID, Status string
	Sequence                                                  int
	OfferExpires                                              string
	NodeID, LabID                                             string
	History                                                   []map[string]any
}
type Handoff struct {
	ID, SampleID, SenderID, ReceiverID, Status string
	SenderConfirmed, ReceiverConfirmed         bool
	CreatedAt                                  string
}
type Audit struct {
	ID, ActorID, Role, Action, EntityType, EntityID string
	Success                                         bool
	At                                              string
	Details                                         map[string]any
}
type State struct {
	Users           map[string]*User
	Locations       map[string]*Location
	Connections     map[string]*Connection
	SampleTypes     map[string]*SampleType
	Samples         map[string]*Sample
	Requests        map[string]map[string]any
	Journeys        map[string]*Journey
	Assignments     map[string]*Assignment
	Handoffs        map[string]*Handoff
	Audits          []Audit
	Events          []map[string]any
	Sessions        map[string]string
	Idempotency     map[string]json.RawMessage
	ServiceVersion  int
	NetworkRevision int
	EventSeq        int
}

type App struct {
	mu    sync.RWMutex
	state State
	file  string
}

func uuid() string {
	b := make([]byte, 16)
	if _, e := rand.Read(b); e != nil {
		return fmt.Sprintf("%d", time.Now().UnixNano())
	}
	b[6] = (b[6] & 15) | 64
	b[8] = (b[8] & 63) | 128
	return fmt.Sprintf("%08x-%04x-%04x-%04x-%012x", b[0:4], b[4:6], b[6:8], b[8:10], b[10:])
}
func now() string          { return time.Now().UTC().Format(time.RFC3339Nano) }
func hash(s string) string { x := sha256.Sum256([]byte(s)); return hex.EncodeToString(x[:]) }
func str(m map[string]any, k string) string {
	if v, ok := m[k].(string); ok {
		return v
	}
	return ""
}
func boolv(m map[string]any, k string, d bool) bool {
	if v, ok := m[k].(bool); ok {
		return v
	}
	return d
}
func num(m map[string]any, k string) float64 {
	if v, ok := m[k].(float64); ok {
		return v
	}
	if v, ok := m[k].(int); ok {
		return float64(v)
	}
	return 0
}
func intval(m map[string]any, k string) int { return int(num(m, k)) }
func arr(m map[string]any, k string) []any {
	if v, ok := m[k].([]any); ok {
		return v
	}
	return nil
}
func idarr(m map[string]any, k string) []string {
	out := []string{}
	for _, x := range arr(m, k) {
		if s, ok := x.(string); ok {
			out = append(out, s)
		}
	}
	return out
}
func iso(v string) time.Time { t, _ := time.Parse(time.RFC3339Nano, v); return t }
func coord(m map[string]any) map[string]any {
	if v, ok := m["origin"].(map[string]any); ok {
		return v
	}
	if v, ok := m["coordinate"].(map[string]any); ok {
		return v
	}
	return nil
}
func validCoord(c map[string]any) bool {
	return c != nil && num(c, "latitude") >= -90 && num(c, "latitude") <= 90 && num(c, "longitude") >= -180 && num(c, "longitude") <= 180
}
func distance(a, b map[string]any) float64 {
	if !validCoord(a) || !validCoord(b) {
		return 1e9
	}
	p := math.Pi / 180
	dlat := (num(b, "latitude") - num(a, "latitude")) * p
	dlon := (num(b, "longitude") - num(a, "longitude")) * p
	x := math.Sin(dlat/2)*math.Sin(dlat/2) + math.Cos(num(a, "latitude")*p)*math.Cos(num(b, "latitude")*p)*math.Sin(dlon/2)*math.Sin(dlon/2)
	return 6371 * 2 * math.Atan2(math.Sqrt(x), math.Sqrt(1-x))
}
func copyMap(m map[string]any) map[string]any {
	b, _ := json.Marshal(m)
	var o map[string]any
	json.Unmarshal(b, &o)
	return o
}

func newState() State {
	return State{Users: map[string]*User{}, Locations: map[string]*Location{}, Connections: map[string]*Connection{}, SampleTypes: map[string]*SampleType{}, Samples: map[string]*Sample{}, Requests: map[string]map[string]any{}, Journeys: map[string]*Journey{}, Assignments: map[string]*Assignment{}, Handoffs: map[string]*Handoff{}, Sessions: map[string]string{}, Idempotency: map[string]json.RawMessage{}, ServiceVersion: 1}
}
func (a *App) load() {
	a.state = newState()
	b, e := os.ReadFile(a.file)
	if e == nil {
		json.Unmarshal(b, &a.state)
	}
	if a.state.Users == nil {
		a.state = newState()
	}
	a.seedTypes()
	a.ensureAdmin()
}
func (a *App) saveLocked() {
	os.MkdirAll(filepath.Dir(a.file), 0755)
	b, _ := json.MarshalIndent(a.state, "", "  ")
	tmp := a.file + ".tmp"
	os.WriteFile(tmp, b, 0600)
	os.Rename(tmp, a.file)
}
func (a *App) seedTypes() {
	defs := []SampleType{{"", "Amber", "amber", "standard", true, false, true, 2, 25, nil}, {"", "Indigo", "indigo", "indigo", true, false, true, 2, 25, nil}, {"", "Frost", "frost", "cooled", true, true, true, 2, 8, nil}, {"", "Pulse", "pulse", "pulse", true, false, false, 2, 25, nil}}
	for _, d := range defs {
		found := false
		for _, x := range a.state.SampleTypes {
			if x.Name == d.Name {
				found = true
			}
		}
		if !found {
			d.ID = uuid()
			a.state.SampleTypes[d.ID] = &d
		}
	}
}
func (a *App) ensureAdmin() {
	if len(a.state.Users) > 0 {
		return
	}
	u := &User{ID: uuid(), Username: os.Getenv("ADMIN_USERNAME"), PasswordHash: hash(os.Getenv("ADMIN_PASSWORD")), FullName: "Initial Administrator", Roles: []string{"administrator"}, Active: true, ActiveRole: "administrator", Available: true, CapacityUnits: 10}
	if u.Username == "" {
		u.Username = "admin"
	}
	a.state.Users[u.ID] = u
	a.saveLocked()
}
func contains(xs []string, s string) bool {
	for _, x := range xs {
		if x == s {
			return true
		}
	}
	return false
}
func (a *App) audit(actor, role, action, et, eid string, success bool, details map[string]any) {
	a.state.Audits = append(a.state.Audits, Audit{uuid(), actor, role, action, et, eid, success, now(), details})
	a.state.EventSeq++
	a.state.Events = append(a.state.Events, map[string]any{"id": a.state.EventSeq, "type": action, "entityType": et, "entityId": eid, "payload": details, "createdAt": now()})
}

func (a *App) auth(r *http.Request) (*User, string, bool) {
	h := r.Header.Get("Authorization")
	if !strings.HasPrefix(h, "Bearer ") {
		return nil, "", false
	}
	tok := strings.TrimSpace(strings.TrimPrefix(h, "Bearer "))
	a.mu.RLock()
	id := a.state.Sessions[tok]
	u := a.state.Users[id]
	a.mu.RUnlock()
	if u == nil || !u.Active {
		return nil, "", false
	}
	return u, u.ActiveRole, true
}
func jsonBody(r *http.Request) (map[string]any, error) {
	b, e := io.ReadAll(io.LimitReader(r.Body, 2<<20))
	if e != nil {
		return nil, e
	}
	var m map[string]any
	e = json.Unmarshal(b, &m)
	return m, e
}
func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	json.NewEncoder(w).Encode(v)
}
func errJSON(w http.ResponseWriter, status int, code, msg string) {
	writeJSON(w, status, map[string]any{"error": msg, "code": code})
}
func dataJSON(w http.ResponseWriter, status int, v any) {
	writeJSON(w, status, map[string]any{"data": v})
}
func requireAuth(a *App, w http.ResponseWriter, r *http.Request) (*User, string, bool) {
	u, role, ok := a.auth(r)
	if !ok {
		errJSON(w, 401, "unauthorized", "authentication required")
	}
	return u, role, ok
}
func requireRole(w http.ResponseWriter, u *User, role string) bool {
	if u == nil {
		return false
	}
	if u.ActiveRole == "" {
		errJSON(w, 409, "role_not_selected", "select an active role first")
		return false
	}
	if u.ActiveRole != role && u.ActiveRole != "administrator" && u.ActiveRole != "dispatcher" {
		errJSON(w, 403, "forbidden", "role cannot perform this action")
		return false
	}
	return true
}
func adminOnly(w http.ResponseWriter, u *User) bool {
	if u == nil {
		return false
	}
	if u.ActiveRole != "administrator" {
		errJSON(w, 403, "forbidden", "administrator role required")
		return false
	}
	return true
}
func idem(a *App, u *User, action string, m map[string]any) (json.RawMessage, bool) {
	k := str(m, "idempotencyKey")
	if k == "" {
		return nil, false
	}
	key := u.ID + ":" + action + ":" + k
	a.mu.RLock()
	v, ok := a.state.Idempotency[key]
	a.mu.RUnlock()
	return v, ok
}
func saveIdem(a *App, u *User, action string, m map[string]any, v any) {
	k := str(m, "idempotencyKey")
	if k != "" {
		b, _ := json.Marshal(map[string]any{"data": v})
		a.state.Idempotency[u.ID+":"+action+":"+k] = b
	}
}

func (a *App) sampleType(id string) *SampleType { return a.state.SampleTypes[id] }
func (a *App) findLab(typeID string) (*Location, int, bool) {
	for _, l := range a.state.Locations {
		if l.Active && l.Functions["laboratory"] && l.Accepted[typeID] {
			return l, 0, true
		}
	}
	return nil, 0, false
}
func (a *App) route(from, to string, cooled bool) ([]string, int, float64, bool) {
	if from == to {
		return []string{from}, 0, 0, true
	}
	type q struct {
		id   string
		path []string
		mins int
		cost float64
	}
	qs := []q{{from, []string{from}, 0, 0}}
	seen := map[string]bool{from: true}
	for len(qs) > 0 {
		x := qs[0]
		qs = qs[1:]
		for _, c := range a.state.Connections {
			if c.From != x.id || !c.Active || (cooled && !c.Cooled) {
				continue
			}
			if seen[c.To] {
				continue
			}
			p := append(append([]string{}, x.path...), c.To)
			if c.To == to {
				return p, x.mins + c.Travel, x.cost + c.Cost, true
			}
			seen[c.To] = true
			qs = append(qs, q{c.To, p, x.mins + c.Travel, x.cost + c.Cost})
		}
	}
	return nil, 0, 0, false
}
func (a *App) service(m map[string]any) (bool, string, *Location, string) {
	typ := a.sampleType(str(m, "sampleTypeId"))
	if typ == nil {
		return false, "no_accepting_laboratory", nil, ""
	}
	origin := coord(m)
	if !validCoord(origin) {
		return false, "invalid_origin", nil, ""
	}
	var from *Location
	for _, l := range a.state.Locations {
		if l.Active && l.Functions["collection_point"] && distance(origin, l.Coordinate) <= l.CoverageKm {
			from = l
			break
		}
	}
	if from == nil {
		return false, "outside_service_coverage", nil, ""
	}
	var lab *Location
	mins := 0
	for _, l := range a.state.Locations {
		if l.Active && l.Functions["laboratory"] && l.Accepted[typ.ID] {
			if _, tm, _, ok := a.route(from.ID, l.ID, typ.Cooled); ok {
				lab = l
				mins = tm
				break
			}
		}
	}
	if lab == nil {
		return false, "no_route", nil, ""
	}
	arrival := iso(str(m, "requestedAt")).Add(time.Duration(mins+from.HandlingMinutes+lab.HandlingMinutes) * time.Minute)
	if !iso(str(m, "deliveryDeadline")).IsZero() && arrival.After(iso(str(m, "deliveryDeadline"))) {
		return false, "deadline_unreachable", lab, arrival.Format(time.RFC3339Nano)
	}
	return true, "serviceable", lab, arrival.Format(time.RFC3339Nano)
}

func (a *App) locationOut(l *Location) map[string]any {
	f := map[string]bool{"collection_point": false, "transfer_point": false, "hub": false, "laboratory": false}
	for k, v := range l.Functions {
		f[k] = v
	}
	return map[string]any{"locationId": l.ID, "name": l.Name, "coordinate": l.Coordinate, "coverageKm": l.CoverageKm, "handlingMinutes": l.HandlingMinutes, "active": l.Active, "functions": f}
}
func (a *App) capacity(l *Location) map[string]any {
	return map[string]any{"capacityUnits": l.Capacity, "reservedUnits": l.Reserved, "availableUnits": l.Capacity - l.Reserved, "cooledCapacityUnits": l.CooledCapacity, "cooledReservedUnits": l.CooledReserved, "cooledAvailableUnits": l.CooledCapacity - l.CooledReserved}
}
func capOut(l *Location) map[string]any {
	return map[string]any{"resourceId": l.ID, "capacityUnits": l.Capacity, "cooledCapacityUnits": l.CooledCapacity}
}
func connectionOut(c *Connection) map[string]any {
	return map[string]any{"connectionId": c.ID, "fromLocationId": c.From, "toLocationId": c.To, "travelMinutes": c.Travel, "costUnits": c.Cost, "cooled": c.Cooled, "active": c.Active}
}
func timeline(s *Sample) []map[string]any { return s.Timeline }
func (a *App) addTimeline(s *Sample, actor, role, action string, details map[string]any) {
	e := map[string]any{"eventId": len(s.Timeline) + 1, "action": action, "actorId": actor, "role": role, "entityType": "sample", "entityId": s.ID, "success": true, "occurredAt": now(), "details": details}
	s.Timeline = append(s.Timeline, e)
	a.audit(actor, role, action, "sample", s.ID, true, details)
}

func (a *App) createJourney(s *Sample, from *Location, lab *Location, home bool) *Journey {
	j := &Journey{ID: uuid(), PlanVersion: 1, RouteMode: "direct", Status: "planned", SampleIDs: []string{s.ID}, CapacityUsed: 1}
	_, mins, cost, ok := a.route(from.ID, lab.ID, a.sampleType(s.TypeID).Cooled)
	if !ok {
		mins = 30
	}
	j.EstimatedDelivery = iso(s.RequestedAt).Add(time.Duration(mins+lab.HandlingMinutes) * time.Minute).Format(time.RFC3339Nano)
	j.Cost = cost
	j.CapacityAvailable = from.Capacity - from.Reserved
	j.Stops = []map[string]any{{"stopId": uuid(), "locationId": from.ID, "stopType": "pickup", "sequence": 1, "estimatedAt": s.RequestedAt}, {"stopId": uuid(), "locationId": lab.ID, "stopType": "delivery", "sequence": 2, "estimatedAt": j.EstimatedDelivery}}
	if home {
		as := &Assignment{ID: uuid(), Kind: "collection", SampleID: s.ID, JourneyID: j.ID, Status: "offered", Sequence: 0, OfferExpires: time.Now().Add(15 * time.Minute).Format(time.RFC3339Nano)}
		a.assignWorker(as, "collection_professional", s)
		a.state.Assignments[as.ID] = as
		j.AssignmentIDs = append(j.AssignmentIDs, as.ID)
		s.ActiveAssignments = append(s.ActiveAssignments, as.ID)
	}
	as := &Assignment{ID: uuid(), Kind: "transport", SampleID: s.ID, JourneyID: j.ID, From: from.ID, To: lab.ID, Status: "offered", Sequence: 1, OfferExpires: time.Now().Add(15 * time.Minute).Format(time.RFC3339Nano), LabID: lab.ID}
	a.assignWorker(as, "delivery_partner", s)
	a.state.Assignments[as.ID] = as
	j.AssignmentIDs = append(j.AssignmentIDs, as.ID)
	s.ActiveAssignments = append(s.ActiveAssignments, as.ID)
	leg := map[string]any{"assignmentId": as.ID, "sequence": 1, "status": as.Status, "fromLocationId": from.ID, "toLocationId": lab.ID, "workerId": as.WorkerID, "sampleId": s.ID}
	j.Legs = []map[string]any{leg}
	s.JourneyID = j.ID
	a.state.Journeys[j.ID] = j
	from.Reserved++
	if a.sampleType(s.TypeID).Cooled {
		from.CooledReserved++
	}
	return j
}
func (a *App) assignWorker(as *Assignment, role string, s *Sample) {
	var best *User
	for _, u := range a.state.Users {
		if u.Active && u.Available && contains(u.Roles, role) {
			typ := a.sampleType(s.TypeID)
			if role == "collection_professional" && typ.Qualified && !contains(u.Qualifications, typ.RequiredQualification) {
				continue
			}
			if best == nil || u.AssignmentCount < best.AssignmentCount {
				best = u
			}
		}
	}
	if best != nil {
		as.WorkerID = best.ID
		best.AssignmentCount++
	}
}

func (a *App) handle(w http.ResponseWriter, r *http.Request) {
	p := r.URL.Path
	if p == "/ready" {
		a.mu.RLock()
		ok := len(a.state.Users) > 0
		a.mu.RUnlock()
		if ok {
			writeJSON(w, 200, map[string]string{"status": "ready"})
		} else {
			writeJSON(w, 503, map[string]string{"status": "starting"})
		}
		return
	}
	if p == "/" || p == "/index.html" {
		http.ServeFile(w, r, "/workspace/web/index.html")
		return
	}
	if strings.HasPrefix(p, "/assets/") {
		http.ServeFile(w, r, "/workspace/web/"+strings.TrimPrefix(p, "/assets/"))
		return
	}
	if p == "/api/authenticate-user" {
		a.login(w, r)
		return
	}
	if p == "/api/events" {
		a.events(w, r)
		return
	}
	if p == "/api/ui/bootstrap" {
		a.bootstrap(w, r)
		return
	}
	if p == "/api/read-sample-state/" || strings.HasPrefix(p, "/api/read-sample-state/") {
		a.readSample(w, r, strings.TrimPrefix(p, "/api/read-sample-state/"))
		return
	}
	if p == "/api/read-user/" || strings.HasPrefix(p, "/api/read-user/") {
		a.readUser(w, r, strings.TrimPrefix(p, "/api/read-user/"))
		return
	}
	if !strings.HasPrefix(p, "/api/") {
		http.NotFound(w, r)
		return
	}
	switch p {
	case "/api/accept-assignment":
		a.accept(w, r)
	case "/api/cancel-journey":
		a.cancel(w, r)
	case "/api/check-serviceability":
		a.check(w, r)
	case "/api/collect-and-seal-sample":
		a.collect(w, r)
	case "/api/configure-capacity":
		a.configureCapacity(w, r)
	case "/api/configure-laboratory-acceptance":
		a.acceptance(w, r)
	case "/api/confirm-handoff":
		a.confirmHandoff(w, r)
	case "/api/confirm-laboratory-receipt":
		a.receipt(w, r)
	case "/api/create-collection-request":
		a.createRequest(w, r, false)
	case "/api/create-connection":
		a.createConnection(w, r)
	case "/api/create-location":
		a.createLocation(w, r, false)
	case "/api/create-sample-type":
		a.createType(w, r, false)
	case "/api/create-user":
		a.createUser(w, r)
	case "/api/decline-assignment":
		a.decline(w, r)
	case "/api/edit-active-plan":
		a.editPlan(w, r)
	case "/api/ingest-presealed-sample":
		a.createRequest(w, r, true)
	case "/api/initiate-handoff":
		a.initiateHandoff(w, r)
	case "/api/list-role-work":
		a.roleWork(w, r)
	case "/api/merge-journeys":
		a.merge(w, r)
	case "/api/read-journey-plan":
		a.readJourney(w, r)
	case "/api/read-operations-state":
		a.operations(w, r)
	case "/api/read-sample-lifecycle":
		a.lifecycle(w, r)
	case "/api/read-serviceability-snapshot":
		a.snapshot(w, r)
	case "/api/record-handling-checkpoint":
		a.checkpoint(w, r)
	case "/api/record-laboratory-exception":
		a.labException(w, r)
	case "/api/record-worker-location":
		a.workerLocation(w, r)
	case "/api/report-disruption":
		a.disruption(w, r)
	case "/api/reroute-journey":
		a.reroute(w, r)
	case "/api/search-audit-trail":
		a.searchAudit(w, r)
	case "/api/select-active-role":
		a.selectRole(w, r)
	case "/api/set-connection-status":
		a.connectionStatus(w, r)
	case "/api/set-location-function-status":
		a.functionStatus(w, r)
	case "/api/set-location-status":
		a.locationStatus(w, r)
	case "/api/set-worker-availability":
		a.workerAvailability(w, r)
	case "/api/split-journey":
		a.split(w, r)
	case "/api/update-assignment-progress":
		a.progress(w, r)
	case "/api/update-location":
		a.createLocation(w, r, true)
	case "/api/update-sample-type":
		a.updateType(w, r)
	case "/api/update-user-access":
		a.updateUser(w, r)
	default:
		http.NotFound(w, r)
	}
}

func (a *App) login(w http.ResponseWriter, r *http.Request) {
	m, e := jsonBody(r)
	if e != nil {
		errJSON(w, 400, "invalid_json", "invalid JSON")
		return
	}
	var u *User
	role := ""
	a.mu.Lock()
	for _, x := range a.state.Users {
		if x.Username == str(m, "username") && x.PasswordHash == hash(str(m, "password")) && x.Active {
			u = x
			break
		}
	}
	if u == nil {
		a.mu.Unlock()
		errJSON(w, 401, "invalid_credentials", "invalid credentials")
		return
	}
	tok := uuid() + uuid()
	a.state.Sessions[tok] = u.ID
	if len(u.Roles) == 1 {
		u.ActiveRole = u.Roles[0]
		role = u.ActiveRole
	} else {
		u.ActiveRole = ""
	}
	a.audit(u.ID, u.ActiveRole, "sign_in", "user", u.ID, true, map[string]any{})
	a.saveLocked()
	a.mu.Unlock()
	dataJSON(w, 200, map[string]any{"sessionToken": tok, "userId": u.ID, "roles": u.Roles, "activeRole": role})
}
func (a *App) events(w http.ResponseWriter, r *http.Request) {
	u, _, ok := requireAuth(a, w, r)
	if !ok {
		return
	}
	since, _ := strconv.Atoi(r.URL.Query().Get("since"))
	a.mu.RLock()
	ev := []map[string]any{}
	for _, x := range a.state.Events {
		if int(num(x, "id")) > since {
			ev = append(ev, x)
		}
	}
	cur := a.state.EventSeq
	a.mu.RUnlock()
	_ = u
	dataJSON(w, 200, map[string]any{"events": ev, "cursor": cur})
}
func (a *App) bootstrap(w http.ResponseWriter, r *http.Request) {
	u, role, ok := requireAuth(a, w, r)
	if !ok {
		return
	}
	a.mu.RLock()
	ops := a.operationsLocked(u)
	ss := []map[string]any{}
	for _, s := range a.state.Samples {
		if s.RequesterID == u.ID {
			ss = append(ss, a.sampleStateLocked(s))
		}
	}
	a.mu.RUnlock()
	user := map[string]any{"userId": u.ID, "username": u.Username, "fullName": u.FullName, "roles": u.Roles, "activeRole": role, "roleSelectionRequired": len(u.Roles) > 1 && role == ""}
	dataJSON(w, 200, map[string]any{"user": user, "serverTime": now(), "requesterSamples": ss, "operations": ops})
}
func (a *App) readSample(w http.ResponseWriter, r *http.Request, id string) {
	u, _, ok := requireAuth(a, w, r)
	if !ok {
		return
	}
	a.mu.RLock()
	s := a.state.Samples[id]
	if s == nil {
		a.mu.RUnlock()
		errJSON(w, 404, "not_found", "sample not found")
		return
	}
	if s.RequesterID != u.ID && u.ActiveRole != "administrator" && u.ActiveRole != "dispatcher" && !contains(s.ActiveAssignments, u.ID) {
		a.mu.RUnlock()
		errJSON(w, 403, "forbidden", "sample access denied")
		return
	}
	v := a.sampleStateLocked(s)
	a.mu.RUnlock()
	dataJSON(w, 200, v)
}
func (a *App) readUser(w http.ResponseWriter, r *http.Request, id string) {
	u, _, ok := requireAuth(a, w, r)
	if !ok {
		return
	}
	if u.ActiveRole != "administrator" && u.ID != id {
		errJSON(w, 403, "forbidden", "access denied")
		return
	}
	a.mu.RLock()
	x := a.state.Users[id]
	a.mu.RUnlock()
	if x == nil {
		errJSON(w, 404, "not_found", "user not found")
		return
	}
	dataJSON(w, 200, a.userOut(x))
}
func (a *App) userOut(u *User) map[string]any {
	return map[string]any{"userId": u.ID, "username": u.Username, "email": u.Email, "fullName": u.FullName, "phone": u.Phone, "roles": u.Roles, "qualifications": u.Qualifications, "certifications": u.Certifications, "active": u.Active}
}

func (a *App) check(w http.ResponseWriter, r *http.Request) {
	u, _, ok := requireAuth(a, w, r)
	if !ok {
		return
	}
	m, e := jsonBody(r)
	if e != nil {
		errJSON(w, 400, "invalid_json", "invalid JSON")
		return
	}
	if !validCoord(coord(m)) {
		errJSON(w, 400, "invalid_origin", "invalid origin")
		return
	}
	if !iso(str(m, "deliveryDeadline")).After(iso(str(m, "requestedAt"))) {
		errJSON(w, 400, "invalid_deadline", "invalid deadline")
		return
	}
	a.mu.RLock()
	yes, reason, lab, arrival := a.service(m)
	ver := a.state.ServiceVersion
	a.mu.RUnlock()
	out := map[string]any{"serviceable": yes, "reason": reason, "serviceabilityVersion": ver}
	if lab != nil {
		out["targetLaboratoryId"] = lab.ID
	}
	if arrival != "" {
		out["estimatedArrivalAt"] = arrival
	}
	a.mu.Lock()
	a.audit(u.ID, u.ActiveRole, "permission_check", "serviceability", strconv.Itoa(ver), true, map[string]any{"serviceable": yes})
	a.saveLocked()
	a.mu.Unlock()
	dataJSON(w, 200, out)
}

func (a *App) createRequest(w http.ResponseWriter, r *http.Request, pre bool) {
	u, role, ok := requireAuth(a, w, r)
	if !ok {
		return
	}
	m, e := jsonBody(r)
	if e != nil {
		errJSON(w, 400, "invalid_json", "invalid JSON")
		return
	}
	if str(m, "originType") == "home" && pre {
		errJSON(w, 400, "invalid_origin_type", "pre-sealed origin cannot be home")
		return
	}
	a.mu.Lock()
	yes, reason, lab, _ := a.service(m)
	typ := a.sampleType(str(m, "sampleTypeId"))
	if typ == nil {
		a.mu.Unlock()
		errJSON(w, 404, "not_found", "sample type not found")
		return
	}
	rid, sid := uuid(), uuid()
	s := &Sample{ID: sid, RequestID: rid, RequesterID: u.ID, TypeID: typ.ID, Status: "sealed", OriginType: str(m, "originType"), Origin: coord(m), RequestedAt: str(m, "requestedAt"), Deadline: str(m, "deliveryDeadline"), Earliest: str(m, "earliestCollectionAt"), Latest: str(m, "latestCollectionAt"), Container: str(m, "containerType"), Tmin: num(m, "temperatureMinC"), Tmax: num(m, "temperatureMaxC"), Incompatible: idarr(m, "incompatibleSampleTypes"), Sealed: pre, Timeline: []map[string]any{}, Location: coord(m)}
	if s.OriginType == "" {
		s.OriginType = "home"
	}
	if s.Earliest == "" {
		s.Earliest = s.RequestedAt
	}
	if s.Latest == "" {
		s.Latest = s.RequestedAt
	}
	if yes {
		s.Status = "collection_offered"
		s.TargetLabID = lab.ID
		var from *Location
		for _, l := range a.state.Locations {
			if l.Active && l.Functions["collection_point"] && distance(s.Origin, l.Coordinate) <= l.CoverageKm {
				from = l
				break
			}
		}
		j := a.createJourney(s, from, lab, !pre)
		_ = j
	}
	a.addTimeline(s, u.ID, role, "request_created", map[string]any{"serviceable": yes})
	a.state.Samples[sid] = s
	a.state.Requests[rid] = map[string]any{"requestId": rid, "sampleId": sid, "requesterId": u.ID, "origin": s.Origin, "originType": s.OriginType, "requestedAt": s.RequestedAt, "deliveryDeadline": s.Deadline, "sampleTypeId": s.TypeID, "serviceable": yes}
	a.saveLocked()
	a.mu.Unlock()
	out := map[string]any{"requestId": rid, "sampleId": sid, "serviceability": map[bool]string{true: "serviceable", false: "unserviceable"}[yes], "activeAssignmentIds": s.ActiveAssignments, "earliestCollectionAt": s.Earliest, "latestCollectionAt": s.Latest, "originType": s.OriginType, "alreadySealed": pre}
	if reason != "serviceable" {
		out["serviceabilityReason"] = reason
	}
	if lab != nil {
		out["targetLaboratoryId"] = lab.ID
	}
	if s.JourneyID != "" {
		out["journeyId"] = s.JourneyID
	}
	dataJSON(w, 201, out)
}

